class Solution:
    def minCost(self, costs: list[list[int]]) -> int:
        if not costs:
            return 0
        prev = costs[0][:]
        for i in range(1, len(costs)):
            curr = [0, 0, 0]
            curr[0] = costs[i][0] + min(prev[1], prev[2])
            curr[1] = costs[i][1] + min(prev[0], prev[2])
            curr[2] = costs[i][2] + min(prev[0], prev[1])
            prev = curr
        return min(prev)

